class _OnboardingScreenState extends State<OnboardingScreen>{static const options=[('PK','Pakistan','PKR','Rs'),('IE','Ireland','EUR','€'),('GB','United Kingdom','GBP','£'),('US','United States','USD','\$'),('AE','United Arab Emirates','AED','AED'),('SA','Saudi Arabia','SAR','SAR'),('IN','India','INR','₹'),('CA','Canada','CAD','C\$'),('AU','Australia','AUD','A\$')];String country='PK',currency='PKR',symbol='Rs';bool busy=false;@override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:560),child:Card(child:Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const CircleAvatar(radius:28,child:Icon(Icons.wallet_rounded)),const SizedBox(height:18),Text('Make PennyPal yours',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Choose your region and the currency PennyPal should use across your money, budgets, goals and reports.'),const SizedBox(height:22),DropdownButtonFormField<String>(initialValue:country,decoration:const InputDecoration(labelText:'Country / region',prefixIcon:Icon(Icons.public_rounded)),items:options.map((o)=>DropdownMenuItem(value:o.$1,child:Text(o.$2))).toList(),onChanged:(v){if(v==null)return;final o=options.firstWhere((x)=>x.$1==v);setState((){country=o.$1;currency=o.$3;symbol=o.$4;});}),const SizedBox(height:14),DropdownButtonFormField<String>(initialValue:currency,decoration:const InputDecoration(labelText:'Primary currency',prefixIcon:Icon(Icons.currency_exchange_rounded)),items:options.map((o)=>o.$3).toSet().map((c){final o=options.firstWhere((x)=>x.$3==c);return DropdownMenuItem(value:c,child:Text('$c (${o.$4})'));}).toList(),onChanged:(v){if(v==null)return;final o=options.firstWhere((x)=>x.$3==v);setState((){currency=o.$3;symbol=o.$4;});}),const SizedBox(height:22),SizedBox(width:double